mapper.select:
SELECT id, code, name, platform_account as platformAccount, short_name as shortName, auth_status AS authStatus, auth_time AS authTime, update_time AS updateTime, update_user_name AS updateUserName, update_user_id AS updateUserId FROM overseas_provider WHERE ${params.sqlMap.default} and is_deleted = FALSE ORDER BY
${item.field} ${item.sort}
create_time DESC

SELECT opw.id as overseasProviderWarehouseId, opw.platform_warehouse_code, opw.platform_warehouse_name, opw.warehouse_id, opw.warehouse_name, opw.warehouse_code, opw.disabled FROM overseas_provider_warehouse as opw LEFT JOIN overseas_provider as op ON opw.main_id = op.id WHERE op.is_deleted = FALSE AND opw.is_deleted = FALSE
AND opw.id = #{params.overseasProviderWarehouseId}
AND opw.platform_warehouse_code = #{params.platformWarehouseCode}
and op.code=#{params.code}
